```sql
-- Tabla de destino
CREATE TABLE IF NOT EXISTS alumnos_destacados (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50),
  apellido VARCHAR(50),
  nota_media DECIMAL(4,2)
);

DELIMITER //

CREATE PROCEDURE sp_alumnos_destacados()
BEGIN
  DECLARE v_id INT;
  DECLARE v_nombre VARCHAR(50);
  DECLARE v_apellido VARCHAR(50);
  DECLARE v_media DECIMAL(4,2);
  DECLARE v_fin BOOLEAN DEFAULT FALSE;

  DECLARE cur CURSOR FOR
    SELECT id, nombre, apellido FROM alumnos;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin = TRUE;

  -- Limpiar tabla anterior
  TRUNCATE TABLE alumnos_destacados;

  OPEN cur;

  mi_bucle: LOOP
    FETCH cur INTO v_id, v_nombre, v_apellido;
    IF v_fin THEN LEAVE mi_bucle; END IF;

    -- Calcular media (puede ser NULL si no tiene notas)
    SELECT ROUND(AVG(n.nota), 2) INTO v_media
    FROM notas n WHERE n.id_alumno = v_id;

    -- Solo insertar si tiene media y es ≥ 7
    IF v_media IS NOT NULL AND v_media >= 7 THEN
      INSERT INTO alumnos_destacados (nombre, apellido, nota_media)
      VALUES (v_nombre, v_apellido, v_media);
    END IF;
  END LOOP;

  CLOSE cur;

  -- Mostrar resultados
  SELECT * FROM alumnos_destacados ORDER BY nota_media DESC;
END //

DELIMITER ;

-- Ejecutar
CALL sp_alumnos_destacados();
```
